"use client";

import { FormEvent, ReactNode, useMemo, useState } from "react";
import {
  Activity, AlertTriangle, ArrowDown, ArrowRight, BarChart3, Bell, BrainCircuit, BriefcaseBusiness,
  Building2, Check, ChevronDown, ChevronRight, CircleDot, Clock3, Database, Download, ExternalLink,
  Eye, FileCheck2, FilePlus2, FileText, Fingerprint, Gauge, GitBranch, Home, Landmark, Layers3,
  Link2, ListFilter, LocateFixed, LockKeyhole, LogOut, Map, MapPin, Menu, Network, Plus, Radar,
  Search, Settings, Shield, ShieldCheck, Sparkles, Target, TimerReset, TrendingUp, UserRound,
  UsersRound, WalletCards, X, Zap,
} from "lucide-react";
import {
  Area, AreaChart, Bar, BarChart, CartesianGrid, Cell, Pie, PieChart, ResponsiveContainer,
  Tooltip as ChartTooltip, XAxis, YAxis,
} from "recharts";
import { CaseRecord, cases as seedCases, intelligenceSources, predictions, timeDistribution, withdrawalTrend } from "./data";

type View = "dashboard" | "cases" | "case" | "intelligence" | "money" | "behaviour" | "predictions" | "map" | "alerts" | "reports" | "settings";

const navItems: { id: View; label: string; icon: typeof Home }[] = [
  { id: "dashboard", label: "Dashboard", icon: Home },
  { id: "cases", label: "Cases", icon: BriefcaseBusiness },
  { id: "intelligence", label: "External Intelligence", icon: Link2 },
  { id: "money", label: "Money Trail", icon: GitBranch },
  { id: "behaviour", label: "Behavioural Intelligence", icon: Fingerprint },
  { id: "predictions", label: "Predictions", icon: BrainCircuit },
  { id: "map", label: "Map Intelligence", icon: Map },
  { id: "alerts", label: "Alerts", icon: Bell },
  { id: "reports", label: "Reports", icon: FileText },
  { id: "settings", label: "Settings & Access", icon: Settings },
];

const predictionSteps = [
  "Analysing complaint", "Tracing fraudulent funds", "Analysing account behaviour", "Analysing historical withdrawals",
  "Correlating external intelligence", "Analysing geographic patterns", "Analysing temporal patterns",
  "Comparing similar cases", "Ranking candidate locations", "Generating prediction",
];

function Logo({ compact = false }: { compact?: boolean }) {
  return <div className={`logo ${compact ? "compact" : ""}`}><div className="logoMark"><Shield/><span /></div>{!compact && <div><b>FINSHIELD</b><small>Predict. Locate. Act.</small></div>}</div>;
}

function DemoBadge() {
  return <span className="demoBadge"><CircleDot size={11}/> DEMO DATA</span>;
}

function StatusBadge({ children, tone = "blue" }: { children: ReactNode; tone?: string }) {
  return <span className={`status ${tone}`}>{children}</span>;
}

function StatCard({ label, value, note, icon: Icon, tone = "blue" }: { label: string; value: string; note: string; icon: typeof Home; tone?: string }) {
  return <div className="statCard"><div className={`statIcon ${tone}`}><Icon size={19}/></div><div><p>{label}</p><strong>{value}</strong><small>{note}</small></div></div>;
}

function SectionTitle({ eyebrow, title, description, action }: { eyebrow?: string; title: string; description?: string; action?: ReactNode }) {
  return <div className="sectionTitle"><div>{eyebrow && <span>{eyebrow}</span>}<h2>{title}</h2>{description && <p>{description}</p>}</div>{action}</div>;
}

function Modal({ title, children, onClose, wide = false }: { title: string; children: ReactNode; onClose: () => void; wide?: boolean }) {
  return <div className="modalBackdrop" onMouseDown={onClose}><div className={`modal ${wide ? "wide" : ""}`} onMouseDown={e => e.stopPropagation()}><div className="modalHead"><div><DemoBadge/><h3>{title}</h3></div><button className="iconButton" onClick={onClose}><X size={18}/></button></div>{children}</div></div>;
}

function Login({ onLogin }: { onLogin: () => void }) {
  const [show, setShow] = useState(false);
  const submit = (e: FormEvent) => { e.preventDefault(); onLogin(); };
  return <main className="loginPage">
    <div className="loginGlow one"/><div className="loginGlow two"/>
    <section className="loginStory">
      <Logo />
      <div className="storyCopy"><DemoBadge/><h1>Don’t wait for<br/>the <em>cash-out.</em></h1><p>Predict where it is likely to happen. Understand why. Prioritize the right location. Act in time.</p></div>
      <div className="intelligenceFlow"><span>Complaint</span><ArrowRight/><span>Intelligence</span><ArrowRight/><span>Prediction</span><ArrowRight/><span>Action</span></div>
      <div className="loginStats"><div><strong>87%</strong><small>Top location signal</small></div><div><strong>6</strong><small>Correlated sources</small></div><div><strong>10–12</strong><small>Predicted window</small></div></div>
    </section>
    <section className="loginPanel">
      <form className="loginCard" onSubmit={submit}>
        <div className="securePill"><ShieldCheck size={14}/> SECURE LAW ENFORCEMENT ENVIRONMENT</div>
        <h2>Investigator access</h2><p>Predictive Cybercrime Intelligence Platform</p>
        <label>INVESTIGATOR ID / USERNAME<div className="inputWrap"><UserRound size={17}/><input autoComplete="username" defaultValue="INV-024" required/></div></label>
        <label>PASSWORD<div className="inputWrap"><LockKeyhole size={17}/><input autoComplete="current-password" type={show ? "text" : "password"} defaultValue="finshield" required/><button type="button" aria-label="Show password" onClick={() => setShow(!show)}><Eye size={17}/></button></div></label>
        <div className="loginMeta"><label className="check"><input type="checkbox" defaultChecked/> Keep session active</label><span>Authorized personnel only</span></div>
        <button className="primaryButton loginButton" type="submit">ENTER COMMAND CENTRE <ArrowRight size={18}/></button>
        <div className="prototypeNote"><AlertTriangle size={15}/><span><b>Prototype environment.</b> Uses fully synthetic data. Institutional integrations require authorized access.</span></div>
      </form>
    </section>
  </main>;
}

export default function FinshieldApp() {
  const [loggedIn, setLoggedIn] = useState(false);
  const [view, setView] = useState<View>("dashboard");
  const [selectedCase, setSelectedCase] = useState<CaseRecord>(seedCases[0]);
  const [caseList, setCaseList] = useState(seedCases);
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [modal, setModal] = useState<string | null>(null);
  const [toast, setToast] = useState<string | null>(null);
  const [alertCount, setAlertCount] = useState(18);
  const [predictionDone, setPredictionDone] = useState(false);
  const [predictionRunning, setPredictionRunning] = useState(false);
  const [predictionStep, setPredictionStep] = useState(-1);
  const [selectedAtm, setSelectedAtm] = useState(predictions[0]);

  const notify = (message: string) => { setToast(message); window.setTimeout(() => setToast(null), 2800); };
  const openCase = (item: CaseRecord) => { setSelectedCase(item); setView("case"); setSidebarOpen(false); };
  const navigate = (next: View) => { setView(next); setSidebarOpen(false); };
  const runPrediction = async () => {
    if (predictionRunning) return;
    setPredictionRunning(true); setPredictionDone(false); setPredictionStep(0); setModal("prediction");
    for (let index = 0; index < predictionSteps.length; index += 1) {
      setPredictionStep(index);
      await new Promise(resolve => window.setTimeout(resolve, 330));
    }
    setPredictionStep(predictionSteps.length); setPredictionDone(true); setPredictionRunning(false);
    notify("Prediction generated for CC-1024");
  };
  const createAlert = () => { setAlertCount(count => count + 1); notify("High-priority cash-out alert created"); };
  const addCase = (e: FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const data = new FormData(e.currentTarget);
    const newCase: CaseRecord = { id: `CC-${1048 + caseList.length - 24}`, type: String(data.get("type")), amount: String(data.get("amount")), city: String(data.get("city")), area: String(data.get("area")), status: "New", priority: "High", prediction: "Pending", date: "01 Sep 2026" };
    setCaseList(list => [newCase, ...list]); setSelectedCase(newCase); setModal(null); setView("case"); notify(`${newCase.id} registered successfully`);
  };

  if (!loggedIn) return <Login onLogin={() => setLoggedIn(true)}/>;

  return <div className="appShell">
    <aside className={`sidebar ${sidebarOpen ? "open" : ""}`}>
      <div className="sidebarTop"><Logo/><button className="mobileClose" onClick={() => setSidebarOpen(false)}><X/></button></div>
      <div className="workspaceLabel">INTELLIGENCE WORKSPACE</div>
      <nav>{navItems.map(item => <button key={item.id} className={view === item.id || (view === "case" && item.id === "cases") ? "active" : ""} onClick={() => navigate(item.id)}><item.icon size={18}/><span>{item.label}</span>{item.id === "alerts" && <b>{alertCount}</b>}</button>)}</nav>
      <div className="sidebarUser"><div className="avatar">AK<span /></div><div><strong>Investigator A. Kumar</strong><small>Cyber Crime Investigator</small><em>● Online</em></div><ChevronDown size={15}/></div>
    </aside>
    {sidebarOpen && <div className="sidebarScrim" onClick={() => setSidebarOpen(false)}/>} 
    <main className="mainArea">
      <header className="topbar"><div className="topbarLeft"><button className="menuButton" onClick={() => setSidebarOpen(true)}><Menu/></button><div className="breadcrumb"><span>FINSHIELD</span><ChevronRight size={13}/><b>{view === "case" ? selectedCase.id : navItems.find(n => n.id === view)?.label}</b></div></div><div className="topbarRight"><DemoBadge/><button className="iconButton" onClick={() => navigate("alerts")}><Bell size={18}/><i>{alertCount}</i></button><button className="iconButton" onClick={() => setLoggedIn(false)}><LogOut size={18}/></button></div></header>
      <div className="content">
        {view === "dashboard" && <Dashboard onCase={openCase} onNavigate={navigate} onPredict={runPrediction}/>} 
        {view === "cases" && <CasesView cases={caseList} onCase={openCase} onCreate={() => setModal("newCase")}/>} 
        {view === "case" && <CaseView record={selectedCase} onNavigate={navigate} onPredict={runPrediction} notify={notify}/>} 
        {view === "intelligence" && <IntelligenceView onDetails={name => setModal(`source:${name}`)} onNavigate={navigate} notify={notify}/>} 
        {view === "money" && <MoneyTrail onNode={name => { setModal(`node:${name}`); }} />} 
        {view === "behaviour" && <BehaviourView/>} 
        {view === "predictions" && <PredictionsView done={predictionDone} onPredict={runPrediction} onMap={() => navigate("map")} onAlert={createAlert}/>} 
        {view === "map" && <MapView selected={selectedAtm} setSelected={setSelectedAtm} onAlert={createAlert}/>} 
        {view === "alerts" && <AlertsView count={alertCount} onCase={() => openCase(seedCases[0])} onMap={() => navigate("map")} notify={notify}/>} 
        {view === "reports" && <ReportsView onGenerate={() => setModal("report")} notify={notify}/>} 
        {view === "settings" && <SettingsView/>} 
      </div>
    </main>
    {toast && <div className="toast"><Check size={17}/>{toast}</div>}

    {modal === "newCase" && <Modal title="Register new cybercrime case" onClose={() => setModal(null)} wide><NewCaseForm onSubmit={addCase}/></Modal>}
    {modal === "prediction" && <Modal title="Cash-out prediction engine" onClose={() => !predictionRunning && setModal(null)} wide><PredictionProgress step={predictionStep} done={predictionDone} onOpen={() => { setModal(null); setView("predictions"); }}/></Modal>}
    {modal === "report" && <Modal title="Cybercrime Predictive Intelligence Report" onClose={() => setModal(null)} wide><ReportPreview onExport={() => { window.print(); notify("Report prepared for export"); }}/></Modal>}
    {modal?.startsWith("source:") && <Modal title={modal.replace("source:", "")} onClose={() => setModal(null)}><SourceDetail source={modal.replace("source:", "")}/></Modal>}
    {modal?.startsWith("node:") && <Modal title="Network entity details" onClose={() => setModal(null)}><NodeDetail name={modal.replace("node:", "")}/></Modal>}
  </div>;
}

function Dashboard({ onCase, onNavigate, onPredict }: { onCase: (c: CaseRecord) => void; onNavigate: (v: View) => void; onPredict: () => void }) {
  return <>
    <section className="heroPanel"><div className="heroCopy"><span className="eyebrow"><Sparkles size={13}/> PREDICTIVE INTERVENTION</span><h1>Don’t wait for the <em>cash-out.</em></h1><p>Predict where it is likely to happen. Understand why. Prioritize the right location. Act in time.</p><div className="heroActions"><button className="primaryButton" onClick={onPredict}><Radar size={18}/> RUN LIVE DEMO PREDICTION</button><button className="secondaryButton" onClick={() => onCase(seedCases[0])}>OPEN CC-1024 <ArrowRight size={17}/></button></div></div><div className="heroRadar"><div className="radar"><i/><i/><i/><span className="pulse one"/><span className="pulse two"/><div className="targetPoint"><MapPin/><b>ATM-104</b><small>87% likelihood</small></div></div></div></section>
    <div className="pageIntro"><div><span>COMMAND DASHBOARD</span><h2>Cybercrime Intelligence Dashboard</h2><p>Monitor active investigations, financial trails and predicted cash-out activity.</p></div><div className="liveStamp"><Activity size={16}/> Intelligence updated 2 min ago</div></div>
    <section className="statsGrid six"><StatCard label="Total Cybercrime Cases" value="1,284" note="+42 this month" icon={BriefcaseBusiness}/><StatCard label="Active Investigations" value="147" note="11 updated today" icon={Activity} tone="cyan"/><StatCard label="High Priority Cases" value="32" note="Requires attention" icon={AlertTriangle} tone="red"/><StatCard label="Predictions Generated" value="428" note="81.4% location accuracy" icon={BrainCircuit} tone="violet"/><StatCard label="Active Alerts" value="18" note="6 high priority" icon={Bell} tone="amber"/><StatCard label="High-Risk Locations" value="26" note="Across 9 districts" icon={MapPin} tone="green"/></section>
    <div className="dashboardGrid"><section className="panel span2"><SectionTitle eyebrow="ACTIVE INTELLIGENCE" title="High priority cases" action={<button className="textButton" onClick={() => onNavigate("cases")}>View all <ArrowRight size={15}/></button>}/><CaseTable items={seedCases.slice(0, 5)} onCase={onCase}/></section><section className="panel"><SectionTitle eyebrow="RISK RADAR" title="Top cash-out locations"/><div className="rankList">{predictions.slice(0, 4).map(p => <button key={p.atm} onClick={() => onNavigate("map")}><span>{p.rank}</span><div><b>{p.atm}</b><small>{p.area}</small></div><strong>{p.probability}%</strong><i style={{ width: `${p.probability}%` }}/></button>)}</div></section></div>
    <div className="dashboardGrid bottom"><section className="panel"><SectionTitle eyebrow="ALERT STREAM" title="Recent intelligence alerts"/><AlertMini icon={Bell} title="High-priority cash-out signal" body="ATM-104 • 10 PM–12 AM • CC-1024" time="2 min"/><AlertMini icon={Link2} title="Cross-source match identified" body="6 intelligence connections • CC-1024" time="8 min"/><AlertMini icon={TrendingUp} title="Prediction ranking updated" body="New behavioural signal raised ATM-221" time="21 min"/></section><section className="panel span2"><SectionTitle eyebrow="OPERATIONAL OVERVIEW" title="Prediction activity"/><div className="miniAnalytics"><div className="chartBox"><ResponsiveContainer width="100%" height={180}><AreaChart data={withdrawalTrend}><defs><linearGradient id="dashGradient" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#22d3ee" stopOpacity={0.4}/><stop offset="100%" stopColor="#22d3ee" stopOpacity={0}/></linearGradient></defs><CartesianGrid stroke="#20354a" vertical={false}/><XAxis dataKey="day" tick={{ fill: "#738da5", fontSize: 10 }} axisLine={false}/><YAxis hide/><ChartTooltip contentStyle={{ background: "#0b1826", border: "1px solid #27435d" }}/><Area type="monotone" dataKey="amount" stroke="#22d3ee" fill="url(#dashGradient)" strokeWidth={2}/></AreaChart></ResponsiveContainer></div><div className="modelHealth"><span><b>MODEL SIGNAL</b><em>Operational</em></span><div className="healthScore"><Gauge/><strong>92</strong><small>/100</small></div><p>Demo prediction services are functioning normally.</p></div></div></section></div>
  </>;
}

function CaseTable({ items, onCase }: { items: CaseRecord[]; onCase: (c: CaseRecord) => void }) {
  return <div className="tableWrap"><table><thead><tr><th>Case ID</th><th>Crime type</th><th>Fraud amount</th><th>Location</th><th>Status</th><th>Priority</th><th>Prediction</th><th/></tr></thead><tbody>{items.map(item => <tr key={item.id} onClick={() => onCase(item)}><td><b>{item.id}</b></td><td>{item.type}</td><td>{item.amount}</td><td>{item.city}</td><td><StatusBadge tone="blue">{item.status}</StatusBadge></td><td><StatusBadge tone={item.priority === "Critical" || item.priority === "High" ? "red" : item.priority === "Medium" ? "amber" : "green"}>{item.priority.toUpperCase()}</StatusBadge></td><td><span className="predictionCell"><Sparkles size={13}/>{item.prediction}</span></td><td><button className="rowButton"><ChevronRight/></button></td></tr>)}</tbody></table></div>;
}

function AlertMini({ icon: Icon, title, body, time }: { icon: typeof Bell; title: string; body: string; time: string }) {
  return <div className="alertMini"><div className="alertIcon"><Icon size={17}/></div><div><b>{title}</b><p>{body}</p></div><small>{time}</small></div>;
}

function CasesView({ cases, onCase, onCreate }: { cases: CaseRecord[]; onCase: (c: CaseRecord) => void; onCreate: () => void }) {
  const [search, setSearch] = useState(""); const [priority, setPriority] = useState("All"); const [status, setStatus] = useState("All");
  const filtered = useMemo(() => cases.filter(c => `${c.id} ${c.type} ${c.city}`.toLowerCase().includes(search.toLowerCase()) && (priority === "All" || c.priority === priority) && (status === "All" || c.status === status)), [cases, search, priority, status]);
  return <><SectionTitle eyebrow="CASE OPERATIONS" title="Case Management" description="Search, prioritize and manage synthetic cybercrime investigations." action={<button className="primaryButton" onClick={onCreate}><Plus size={17}/> REGISTER NEW CASE</button>}/><div className="filterBar"><div className="searchBox"><Search size={17}/><input placeholder="Search case ID, crime type or city…" value={search} onChange={e => setSearch(e.target.value)}/></div><select value={priority} onChange={e => setPriority(e.target.value)}><option>All</option><option>Critical</option><option>High</option><option>Medium</option><option>Low</option></select><select value={status} onChange={e => setStatus(e.target.value)}><option>All</option><option>New</option><option>Under Investigation</option><option>Monitoring</option><option>Resolved</option><option>Closed</option></select><button className="filterButton"><ListFilter size={16}/> Filters</button></div><section className="panel"><div className="tableMeta"><span><b>{filtered.length}</b> cases shown</span><DemoBadge/></div><CaseTable items={filtered} onCase={onCase}/></section></>;
}

function CaseView({ record, onNavigate, onPredict, notify }: { record: CaseRecord; onNavigate: (v: View) => void; onPredict: () => void; notify: (s: string) => void }) {
  const [tab, setTab] = useState("Overview"); const tabs = ["Overview", "Money Trail", "Behaviour", "Similar Cases", "External Intelligence", "Prediction", "Map", "Timeline"];
  const jump = (name: string) => { setTab(name); if (name === "Money Trail") onNavigate("money"); if (name === "Behaviour") onNavigate("behaviour"); if (name === "External Intelligence") onNavigate("intelligence"); if (name === "Prediction") onNavigate("predictions"); if (name === "Map") onNavigate("map"); };
  return <><div className="caseHeader"><div><div className="caseMeta"><DemoBadge/><StatusBadge tone="red">{record.priority.toUpperCase()} PRIORITY</StatusBadge><StatusBadge>{record.status}</StatusBadge></div><h1>{record.id} <span>• {record.type}</span></h1><p>{record.city}, {record.area} • Complaint registered {record.date}</p></div><div className="caseAmount"><small>FRAUD AMOUNT</small><strong>{record.amount}</strong><span>Transaction TXN-84921</span></div><div className="caseActions"><button className="secondaryButton" onClick={() => notify("Case note recorded in demo log")}><FilePlus2 size={16}/> ADD ACTION</button><button className="primaryButton" onClick={onPredict}><Radar size={17}/> RUN PREDICTION</button></div></div><div className="tabs">{tabs.map(name => <button key={name} className={tab === name ? "active" : ""} onClick={() => jump(name)}>{name}</button>)}</div><div className="caseGrid"><section className="panel"><SectionTitle eyebrow="CASE SUMMARY" title="Complaint intelligence"/><div className="detailGrid"><Detail label="Crime type" value={record.type}/><Detail label="Fraud date/time" value="29 Aug 2026, 8:32 PM"/><Detail label="Victim location" value={`${record.city}, Rajasthan`}/><Detail label="Transaction ID" value="TXN-84921"/><Detail label="Suspicious account" value="XXXX7822" warning/><Detail label="Current fund status" value="Partially dispersed" warning/></div><div className="fundSummary"><div className="fundNode source"><span>ORIGINAL TRANSACTION</span><b>XXXX4521</b><small>Source account</small></div><ArrowRight/><div className="fundNode flagged"><span>FLAGGED DESTINATION</span><b>XXXX7822</b><small>{record.amount}</small></div><ArrowRight/><div className="fundNode"><span>INTERMEDIARY</span><b>XXXX9012</b><small>Potential mule link</small></div></div></section><section className="panel priorityPanel"><SectionTitle eyebrow="INTELLIGENCE SCORE" title="Correlation priority"/><div className="scoreRing"><div><strong>84</strong><small>/100</small></div></div><StatusBadge tone="red">HIGH CORRELATION</StatusBadge><p>An investigation-priority signal—not a determination of guilt.</p><ul className="scoreFactors"><li>NCRP potential match <b>+20</b></li><li>Bank transaction match <b>+18</b></li><li>Historical case match <b>+15</b></li><li>Behavioural match <b>+14</b></li><li>Geo-temporal match <b>+17</b></li></ul></section></div><div className="caseGrid lower"><section className="panel"><SectionTitle eyebrow="EXTERNAL INTELLIGENCE" title="Cross-source verification" action={<button className="textButton" onClick={() => onNavigate("intelligence")}>Open intelligence <ArrowRight size={15}/></button>}/><div className="compactSources">{intelligenceSources.slice(0, 5).map(source => <div key={source.name}><span className={source.tone}/><div><b>{source.name}</b><small>{source.status}</small></div><StatusBadge tone={source.tone}>{source.name === "NCRP" || source.name === "Suspect Registry" ? "VERIFY" : "DEMO"}</StatusBadge></div>)}</div></section><section className="panel"><SectionTitle eyebrow="CASE TIMELINE" title="Latest investigation activity"/><Timeline compact/></section></div></>;
}

function Detail({ label, value, warning }: { label: string; value: string; warning?: boolean }) { return <div className={warning ? "warning" : ""}><small>{label}</small><b>{value}</b></div>; }

function IntelligenceView({ onDetails, onNavigate, notify }: { onDetails: (n: string) => void; onNavigate: (v: View) => void; notify: (s: string) => void }) {
  const [query, setQuery] = useState("XXXX7822"); const [searched, setSearched] = useState(true);
  return <><SectionTitle eyebrow="AUTHORIZED SOURCE CORRELATION" title="External Intelligence & Verification" description="Correlate authorized external intelligence with active investigations."/><div className="notice"><ShieldCheck/><div><b>Demo Environment — Synthetic Data</b><p>No live government or financial systems are connected. Production integrations require authorized institutional access.</p></div><StatusBadge tone="green">RESPONSIBLE DATA MODE</StatusBadge></div><div className="intelSearch"><div><Search/><input value={query} onChange={e => setQuery(e.target.value)} placeholder="Account / UPI ID / Mobile / Email / Transaction ID"/></div><button className="primaryButton" onClick={() => { setSearched(true); notify(`6 connections identified for ${query}`); }}><Radar size={17}/> SEARCH INTELLIGENCE</button></div>{searched && <><div className="resultStrip"><div><span>SEARCHED IDENTIFIER</span><b>{query}</b><small>Bank account • Synthetic identifier</small></div><ArrowRight/><div><span>CROSS-SOURCE MATCHES</span><b>6 intelligence connections</b><small>Potential matches require verification</small></div><div className="correlationMini"><strong>84</strong><span>HIGH<br/>CORRELATION</span></div></div><div className="sourceGrid">{intelligenceSources.map(source => <button className="sourceCard" key={source.name} onClick={() => onDetails(source.name)}><div className={`sourceIcon ${source.tone}`}>{source.name === "NCRP" ? <Landmark/> : source.name.includes("Bank") ? <Building2/> : source.name.includes("Mule") ? <Network/> : <Database/>}</div><div className="sourceTop"><small>AUTHORIZED SOURCE / DEMO</small><ExternalLink size={14}/></div><h3>{source.name}</h3><StatusBadge tone={source.tone}>{source.status}</StatusBadge><p>{source.records}</p><div className="sourceFooter"><span>29 Aug 2026 • 10:32 PM</span><b>{source.verification}</b></div></button>)}</div><section className="panel correlationPanel"><SectionTitle eyebrow="HERO FEATURE" title="Intelligence correlation engine" description="Supporting evidence flows through verified analytical layers before a probabilistic prediction."/><div className="correlationFlow"><div className="sourceStack"><span>NCRP <i>Potential match</i></span><span>CFCFRMS / 1930 <i>Complaint found</i></span><span>Bank Intelligence <i>6 transactions</i></span><span>Historical Cases <i>37 matches</i></span></div><ArrowRight/><div className="correlationNode"><Network/><b>Account<br/>XXXX7822</b><small>6 connections</small></div><ArrowRight/><div className="engineStack"><span><Fingerprint/> Behavioural Intelligence</span><span><MapPin/> Geo-Temporal Intelligence</span><span><BrainCircuit/> Predictive Engine</span></div><ArrowRight/><button className="predictionOutput" onClick={() => onNavigate("predictions")}><Target/><small>LIKELY CASH-OUT</small><b>ATM-104</b><strong>87%</strong></button></div></section></>}
  </>;
}

function MoneyTrail({ onNode }: { onNode: (n: string) => void }) {
  const nodes = [{ label: "Victim account", id: "XXXX4521", amount: "₹1,50,000", kind: "source" }, { label: "Suspicious account", id: "XXXX7822", amount: "₹1,50,000", kind: "risk" }, { label: "Potential mule", id: "XXXX9012", amount: "₹1,00,000", kind: "amber" }, { label: "Secondary account", id: "XXXX3384", amount: "₹75,000", kind: "blue" }, { label: "Likely cash-out", id: "ATM-104", amount: "₹35,000", kind: "target" }];
  return <><SectionTitle eyebrow="FINANCIAL INTELLIGENCE" title="Money Trail & Crime Network" description="Trace synthetic fund movement and inspect potential intermediary relationships." action={<DemoBadge/>}/><section className="panel"><div className="trailSummary"><div><small>ORIGINAL FRAUD AMOUNT</small><b>₹1,50,000</b></div><div><small>ACCOUNTS TRAVERSED</small><b>4</b></div><div><small>FUNDS IDENTIFIED</small><b>₹1,25,000</b></div><div><small>POTENTIAL CASH-OUT</small><b>₹35,000</b></div></div><div className="networkCanvas"><div className="networkGrid"/>{nodes.map((node, index) => <div className="networkStep" key={node.id}>{index > 0 && <div className="transactionEdge"><ArrowRight/><span>{node.amount}<small>{index === 1 ? "UPI" : index === 4 ? "Predicted" : "IMPS"}</small></span></div>}<button className={`networkNode ${node.kind}`} onClick={() => onNode(node.id)}><WalletCards/><span>{node.label}</span><b>{node.id}</b><small>{index === 2 ? "82/100 mule score" : node.amount}</small></button></div>)}</div><div className="networkLegend"><span><i className="source"/> Source</span><span><i className="risk"/> Flagged</span><span><i className="amber"/> Requires investigation</span><span><i className="target"/> Predicted location</span></div></section><div className="dashboardGrid"><section className="panel span2"><SectionTitle eyebrow="TRANSACTION LEDGER" title="Suspicious movement"/><TransactionTable/></section><section className="panel"><SectionTitle eyebrow="POTENTIAL INTERMEDIARY" title="Mule account analysis"/><div className="muleScore"><div><strong>82</strong><small>/100</small></div><StatusBadge tone="amber">REQUIRES INVESTIGATION</StatusBadge></div><div className="detailGrid single"><Detail label="Account" value="XXXX9012"/><Detail label="Linked transactions" value="14"/><Detail label="Incoming amount" value="₹4,20,000"/><Detail label="Outgoing amount" value="₹3,80,000"/></div><p className="responsibleNote">This score indicates investigation priority and does not establish criminality.</p></section></div></>;
}

function TransactionTable() { const rows = [["TXN-84921", "8:32 PM", "₹1,50,000", "XXXX4521", "XXXX7822", "Flagged"], ["TXN-84928", "8:45 PM", "₹1,00,000", "XXXX7822", "XXXX9012", "Reviewed"], ["TXN-84934", "9:10 PM", "₹75,000", "XXXX9012", "XXXX3384", "Flagged"], ["TXN-84941", "9:24 PM", "₹25,000", "XXXX7822", "XXXX6140", "Monitoring"]]; return <div className="tableWrap"><table><thead><tr>{["Transaction", "Time", "Amount", "Source", "Destination", "Status"].map(h => <th key={h}>{h}</th>)}</tr></thead><tbody>{rows.map(row => <tr key={row[0]}>{row.map((cell, i) => <td key={cell}>{i === 5 ? <StatusBadge tone={cell === "Flagged" ? "red" : "blue"}>{cell}</StatusBadge> : i === 0 ? <b>{cell}</b> : cell}</td>)}</tr>)}</tbody></table></div>; }

function BehaviourView() {
  return <><SectionTitle eyebrow="BEHAVIOURAL ANALYTICS" title="Account Behavioural Fingerprint" description="Patterns derived from synthetic historical account activity." action={<DemoBadge/>}/><section className="fingerprintHero"><div className="fingerVisual"><Fingerprint/><i/><i/><i/></div><div><small>ANALYSED IDENTIFIER</small><h2>Account XXXX7822</h2><p>Behavioural pattern consistency is high across withdrawal timing, amount and location cluster.</p><div><StatusBadge tone="violet">87% PATTERN SIMILARITY</StatusBadge><StatusBadge tone="amber">REQUIRES VERIFICATION</StatusBadge></div></div><div className="fingerMetrics"><Metric label="Avg. withdrawal" value="₹35,000"/><Metric label="Typical time" value="9 PM – 12 AM"/><Metric label="Previous withdrawals" value="12"/><Metric label="Frequent cluster" value="Jaipur South • C4"/></div></section><div className="chartGrid"><section className="panel"><SectionTitle eyebrow="AMOUNT PATTERN" title="Withdrawal amount over time"/><ResponsiveContainer width="100%" height={240}><AreaChart data={withdrawalTrend}><defs><linearGradient id="behGradient" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#8b5cf6" stopOpacity={0.42}/><stop offset="100%" stopColor="#8b5cf6" stopOpacity={0}/></linearGradient></defs><CartesianGrid stroke="#20354a" vertical={false}/><XAxis dataKey="day" tick={{ fill: "#7890a6", fontSize: 11 }} axisLine={false}/><YAxis tick={{ fill: "#7890a6", fontSize: 11 }} axisLine={false}/><ChartTooltip contentStyle={{ background: "#0b1826", border: "1px solid #27435d" }}/><Area type="monotone" dataKey="amount" stroke="#a78bfa" fill="url(#behGradient)" strokeWidth={2}/></AreaChart></ResponsiveContainer></section><section className="panel"><SectionTitle eyebrow="TEMPORAL PATTERN" title="Withdrawal time distribution"/><ResponsiveContainer width="100%" height={240}><BarChart data={timeDistribution}><CartesianGrid stroke="#20354a" vertical={false}/><XAxis dataKey="time" tick={{ fill: "#7890a6", fontSize: 10 }} axisLine={false}/><YAxis hide/><ChartTooltip contentStyle={{ background: "#0b1826", border: "1px solid #27435d" }}/><Bar dataKey="count" fill="#22d3ee" radius={[4,4,0,0]}/></BarChart></ResponsiveContainer></section></div><div className="dashboardGrid"><section className="panel span2"><SectionTitle eyebrow="SIMILARITY ENGINE" title="37 similar cases found"/><SimilarCases/></section><section className="panel"><SectionTitle eyebrow="GEO-TEMPORAL SUMMARY" title="Key behavioural signals"/><div className="insightList"><Insight icon={Clock3} title="Peak activity window" value="9 PM – 12 AM"/><Insight icon={MapPin} title="Most frequent area" value="Jaipur South"/><Insight icon={LocateFixed} title="Average distance" value="3.2 km"/><Insight icon={Activity} title="Transaction frequency" value="High"/></div></section></div></>;
}

function Metric({ label, value }: { label: string; value: string }) { return <div><small>{label}</small><b>{value}</b></div>; }
function Insight({ icon: Icon, title, value }: { icon: typeof Home; title: string; value: string }) { return <div><span><Icon/></span><div><small>{title}</small><b>{value}</b></div></div>; }
function SimilarCases() { const rows = [["CC-0872", "UPI Fraud", "₹1,32,000", "Jaipur", "91%", "ATM Cluster 4"], ["CC-0914", "Phishing", "₹92,000", "Jaipur", "86%", "Sodala"], ["CC-0966", "UPI Fraud", "₹1,60,000", "Ajmer", "81%", "Civil Lines"], ["CC-0998", "OTP Fraud", "₹74,000", "Jaipur", "78%", "Mansarovar"]]; return <div className="tableWrap"><table><thead><tr>{["Case", "Crime Type", "Amount", "Location", "Similarity", "Withdrawal"].map(h => <th key={h}>{h}</th>)}</tr></thead><tbody>{rows.map(r => <tr key={r[0]}>{r.map((c, i) => <td key={c}>{i === 4 ? <StatusBadge tone="violet">{c}</StatusBadge> : i === 0 ? <b>{c}</b> : c}</td>)}</tr>)}</tbody></table></div>; }

function PredictionsView({ done, onPredict, onMap, onAlert }: { done: boolean; onPredict: () => void; onMap: () => void; onAlert: () => void }) {
  return <><section className="predictionHero"><div><span className="eyebrow"><BrainCircuit size={14}/> HERO CAPABILITY</span><h1>Cash-out Location Prediction</h1><p>Rank likely withdrawal locations before the cash-out occurs using correlated synthetic intelligence.</p><div><button className="primaryButton" onClick={onPredict}><Radar/> {done ? "RUN UPDATED PREDICTION" : "RUN CASH-OUT PREDICTION"}</button>{done && <StatusBadge tone="green"><Check size={13}/> PREDICTION READY</StatusBadge>}</div></div><div className="topPrediction"><small>TOP PREDICTED LOCATION</small><span><MapPin/> ATM-104</span><b>87%</b><em>HIGH PRIORITY</em><p>Expected window: 10 PM – 12 AM</p></div></section><div className="responsibleBanner"><ShieldCheck/><span><b>Probabilistic prediction—not a certainty.</b> Use as supporting intelligence and follow authorized investigative procedures.</span></div><section className="panel"><SectionTitle eyebrow="RANKED CANDIDATES" title="Predicted cash-out locations" action={<button className="secondaryButton" onClick={onMap}><Map size={16}/> OPEN PREDICTIVE MAP</button>}/><div className="predictionTable">{predictions.map(item => <div key={item.atm} className={item.rank === 1 ? "top" : ""}><span className="rank">#{item.rank}</span><div className="atmName"><MapPin/><div><b>{item.atm}</b><small>{item.area}</small></div></div><div className="probBar"><i style={{ width: `${item.probability}%` }}/></div><strong>{item.probability}%</strong><StatusBadge tone={item.priority === "High" ? "red" : item.priority === "Medium" ? "amber" : "green"}>{item.priority.toUpperCase()}</StatusBadge><span className="time"><Clock3/> {item.time}</span></div>)}</div></section><div className="predictionGrid"><section className="panel"><SectionTitle eyebrow="HIERARCHICAL LOCATION PREDICTION" title="Progressive geographic narrowing"/><div className="hierarchy">{["Rajasthan", "Jaipur", "Vaishali Nagar", "ATM Cluster 4", "ATM-104 • 87%"].map((item, i) => <div key={item} className={i === 4 ? "final" : ""}><span>{i < 4 ? <MapPin/> : <Target/>}</span><b>{item}</b>{i < 4 && <ArrowDown/>}</div>)}</div></section><section className="panel"><SectionTitle eyebrow="EXPLAINABLE AI" title="Why this location?"/><div className="whyList">{["Previous withdrawals occurred nearby", "Similar cybercrime cases used this area", "Historical account behaviour matches", "Withdrawal time pattern matches", "Geographic distance is consistent", "ATM usage frequency is high", "Relevant intelligence correlation"].map(reason => <div key={reason}><Check/>{reason}</div>)}</div><div className="priorityBox"><div><small>LOCATION PRIORITY SCORE</small><b>91<span>/100</span></b></div><StatusBadge tone="red">HIGH PRIORITY</StatusBadge></div></section></div><section className="panel adaptive"><SectionTitle eyebrow="ADAPTIVE RANKING" title="New intelligence changed the ranking" description="Candidate priorities update as new, verified signals become available."/><div className="rankingCompare"><div><small>INITIAL RANKING</small><RankingRows values={[60,55,42]}/></div><div className="updateArrow"><Zap/><span>NEW INTELLIGENCE</span><ArrowRight/></div><div><small>UPDATED RANKING</small><RankingRows values={[81,48,31]} updated/></div><button className="primaryButton" onClick={onAlert}><Bell/> CREATE PROACTIVE ALERT</button></div></section></>;
}

function RankingRows({ values, updated }: { values: number[]; updated?: boolean }) { return <>{values.map((v, i) => <div className="rankingRow" key={v}><b>ATM {String.fromCharCode(65+i)}</b><span><i style={{ width: `${v}%` }}/></span><strong className={updated && i === 0 ? "up" : ""}>{v}%</strong></div>)}</>; }

function MapView({ selected, setSelected, onAlert }: { selected: typeof predictions[number]; setSelected: (p: typeof predictions[number]) => void; onAlert: () => void }) {
  return <><SectionTitle eyebrow="GEO-SPATIAL INTELLIGENCE" title="Predictive Map" description="Explore synthetic hotspots, ATM clusters and ranked cash-out locations." action={<div className="mapLegend"><span><i className="high"/> High</span><span><i className="medium"/> Medium</span><span><i className="low"/> Low activity</span></div>}/><div className="mapLayout"><section className="mapCanvas"><div className="mapRoads"><i/><i/><i/><i/><i/><i/></div><div className="mapRiver"/><div className="areaLabel a">VAISHALI NAGAR</div><div className="areaLabel b">SODALA</div><div className="areaLabel c">CIVIL LINES</div><div className="hotspot h1"/><div className="hotspot h2"/><div className="hotspot h3"/>{predictions.map(p => <button key={p.atm} className={`mapMarker ${p.priority.toLowerCase()} ${selected.atm === p.atm ? "selected" : ""}`} style={{ left: `${p.x}%`, top: `${p.y}%` }} onClick={() => setSelected(p)}><span>{p.probability}%</span><i/><small>{p.atm}</small></button>)}<div className="mapControls"><button>+</button><button>−</button><button><LocateFixed/></button></div><div className="mapLayers"><Layers3/><span>Predicted ATMs</span><span>Hotspots</span><span>Previous withdrawals</span></div><div className="mapDataLabel"><DemoBadge/><span>Synthetic Jaipur geography • Not for operational navigation</span></div></section><aside className="locationPanel"><div className="locationHead"><span className="rank">#{selected.rank}</span><div><small>PREDICTED LOCATION</small><h2>{selected.atm}</h2><p>{selected.area}, Jaipur</p></div><strong>{selected.probability}%</strong></div><StatusBadge tone={selected.priority === "High" ? "red" : "amber"}>{selected.priority.toUpperCase()} PRIORITY</StatusBadge><div className="locationMetrics"><Metric label="Expected cash-out" value={selected.time}/><Metric label="Previous withdrawals" value={`${selected.withdrawals}`}/><Metric label="Average withdrawal" value="₹35,000"/><Metric label="Distance from activity" value="2.4 km"/><Metric label="Similar cases" value="8"/><Metric label="Intel connections" value="6"/></div><div className="locationReasons"><b>Top contributing signals</b><span><Check/> Historical withdrawal proximity</span><span><Check/> Behavioural time match</span><span><Check/> Similar-case geography</span></div><button className="primaryButton full" onClick={onAlert}><Bell/> CREATE LOCATION ALERT</button><button className="secondaryButton full">VIEW FULL INTELLIGENCE</button></aside></div></>;
}

